<script>(function(){
const main=document.getElementById('productMainImage'),stage=document.getElementById('productGalleryStage'),counter=document.getElementById('productGalleryCounter'),source=document.getElementById('productImageSource'),thumbs=[...document.querySelectorAll('[data-gallery-index]')],prev=document.querySelector('[data-gallery-prev]'),next=document.querySelector('[data-gallery-next]');
let current=0,touchX=null;
const showSlide=(idx)=>{if(!main||!thumbs.length)return;current=(idx+thumbs.length)%thumbs.length;const b=thumbs[current];main.classList.add('is-changing');setTimeout(()=>{main.src=b.dataset.gallerySrc||main.src;main.alt=b.dataset.galleryLabel||main.alt;main.classList.remove('is-changing');},80);thumbs.forEach((t,i)=>t.classList.toggle('active',i===current));if(counter)counter.textContent=(current+1)+' / '+thumbs.length;if(source)source.textContent=b.dataset.galleryLabel||'';b.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});};
thumbs.forEach((b,i)=>b.addEventListener('click',()=>showSlide(i)));if(prev)prev.addEventListener('click',()=>showSlide(current-1));if(next)next.addEventListener('click',()=>showSlide(current+1));if(stage){stage.addEventListener('touchstart',e=>{touchX=e.touches[0]?.clientX??null},{passive:true});stage.addEventListener('touchend',e=>{if(touchX===null||!thumbs.length)return;const end=e.changedTouches[0]?.clientX??touchX;const diff=end-touchX;touchX=null;if(Math.abs(diff)>45)showSlide(diff<0?current+1:current-1);},{passive:true});}
const sel=document.getElementById('productVariantSelect'),btn=document.getElementById('productAddCart'),buy=document.getElementById('productBuyNow'),price=document.getElementById('productLivePrice'),stock=document.getElementById('productLiveStock'),meta=document.getElementById('productVariantMeta'),label=document.getElementById('productVariantLabel');if(sel&&btn){const base=JSON.parse(btn.dataset.product||'{}');const formatRupiah=(n)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0);const apply=()=>{const o=sel.options[sel.selectedIndex];const variantStock=Number(o.dataset.stock||0);const variantImage=o.dataset.image||'';const v={...base,variant_id:Number(o.value||0),variant_name:o.dataset.name||'',price:Number(o.dataset.price||0),original_price:Number(o.dataset.originalPrice||o.dataset.price||0),stock:variantStock,weight_gram:Number(o.dataset.weight||base.weight_gram||100),sku:o.dataset.sku||'',image:variantImage||base.image||'',unit:o.dataset.unit||base.unit||'pcs'};btn.dataset.product=JSON.stringify(v);btn.disabled=variantStock<=0;if(buy){buy.dataset.product=JSON.stringify(v);buy.disabled=variantStock<=0;}if(price)price.textContent=formatRupiah(v.price);if(stock){stock.classList.toggle('out',variantStock<=0);stock.innerHTML='<i class="bi bi-box-seam"></i>'+(variantStock>0?'Tersedia '+variantStock+' '+v.unit:'Stok habis');}if(variantImage&&main){main.src=variantImage;if(source)source.textContent='Foto varian: '+(v.variant_name||'');}if(label)label.textContent=v.variant_name||'';if(meta){meta.innerHTML='';[['Varian',v.variant_name||'-'],['Harga',formatRupiah(v.price)],['Stok Varian',(variantStock>0?variantStock+' '+v.unit:'Habis')],['SKU',v.sku||'-']].forEach(([k,val])=>{const span=document.createElement('span');span.className='variant-chip';span.innerHTML='<b>'+k+'</b><small>'+val+'</small>';meta.appendChild(span);});}};sel.addEventListener('change',apply);apply();}
})();</script>
